MERGE erp_bookstore_item AS target
USING (SELECT #{bcode, jdbcType=VARCHAR} AS bcode, #{centerCode, jdbcType=VARCHAR} AS center_code) AS source
ON target.bcode = source.bcode AND target.center_code = source.center_code
WHEN MATCHED THEN UPDATE SET qty = target.qty + #{quantity}
WHEN NOT MATCHED THEN INSERT (bcode, content_id, center_code, book_title, author, publisher, image_url, qty)
    VALUES (source.bcode, #{contentId}, source.center_code, #{bookTitle}, #{author}, #{publisher}, #{imageUrl}, #{quantity});

