MERGE erp_bookstore_item AS target
USING (SELECT TOP 1 bcode, content_id, book_title, author, publisher, image_url
       FROM erp_bookstore_item WHERE bcode = #{bcode}) AS source
ON target.bcode = source.bcode AND target.center_code = #{centerCode, jdbcType=VARCHAR}
WHEN MATCHED THEN UPDATE SET qty = target.qty + #{deltaQty}
WHEN NOT MATCHED THEN INSERT (bcode, content_id, center_code, book_title, author, publisher, image_url, qty)
    VALUES (source.bcode, source.content_id, #{centerCode}, source.book_title, source.author, source.publisher, source.image_url, #{deltaQty});

