UPDATE erp_bookstore_item
SET qty = qty - #{amount}
WHERE bcode = #{bcode} AND center_code = #{centerCode} AND qty - loaned_qty - lost_qty >= #{amount}

mapper.insert:
MERGE erp_bookstore_item AS target
USING (
    SELECT #{bcode, jdbcType=VARCHAR} AS bcode, #{centerCode, jdbcType=VARCHAR} AS center_code,
           c.content_id AS content_id, c.original_title AS book_title, c.author AS author,
           c.publisher AS publisher, c.image_url AS image_url
    FROM erp_bookstore_content c WHERE c.content_id = #{contentId}
) AS source
ON target.bcode = source.bcode AND target.center_code = source.center_code
WHEN MATCHED THEN UPDATE SET qty = target.qty + #{deltaQty}
WHEN NOT MATCHED THEN INSERT (bcode, content_id, center_code, book_title, author, publisher, image_url, qty)
    VALUES (source.bcode, source.content_id, source.center_code, source.book_title, source.author, source.publisher, source.image_url, #{deltaQty});
